{"file_path":"src/parse.js","content":"/**
 * The reader for the configuration document. `parse` turns the text into a
 * tree of nodes, and throws a `ConfError` at the first line that does not fit
 * the grammar.
 *
 * A node is one of
 *   { kind: 'table',   entries: Map, header: boolean }
 *   { kind: 'array',   items: [],    aot: boolean }
 *   { kind: 'string' | 'integer' | 'float' | 'boolean', value }
 */
import { ConfError, pathJoin } from './errors.js'

const INTEGER = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/

const isSpace = (c) => c === ' ' || c === '\t'
const isComment = (c) => c === '#' || c === ';'
const isBareName = (c) =>
  (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '_' || c === '-'
const isHex = (c) =>
  (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')

export function newTable() {
  return { kind: 'table', entries: new Map(), header: false }
}

/** One line of the document, read left to right. */
class Line {
  constructor(text, number) {
    this.s = text
    this.i = 0
    this.number = number
  }

  fail(reason) {
    throw new ConfError(this.number, reason)
  }

  peek() {
    return this.i < this.s.length ? this.s[this.i] : ''
  }

  done() {
    return this.i >= this.s.length
  }

  /** True where nothing meaningful is left: the end of the line or a comment. */
  spent() {
    return this.done() || isComment(this.peek())
  }

  spaces() {
    while (isSpace(this.peek())) this.i += 1
  }

  basicString() {
    this.i += 1
    let out = ''
    for (;;) {
      if (this.done()) this.fail('unterminated string')
      const c = this.s[this.i]
      this.i += 1
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      if (this.done()) this.fail('unterminated string')
      const e = this.s[this.i]
      this.i += 1
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const hex = this.s.slice(this.i, this.i + 4)
        if (hex.length !== 4 || ![...hex].every(isHex)) this.fail('invalid escape \\u')
        this.i += 4
        out += String.fromCharCode(parseInt(hex, 16))
      } else this.fail(`invalid escape \\${e}`)
    }
  }

  literalString() {
    this.i += 1
    const start = this.i
    for (;;) {
      if (this.done()) this.fail('unterminated string')
      if (this.s[this.i] === "'") {
        const out = this.s.slice(start, this.i)
        this.i += 1
        return out
      }
      this.i += 1
    }
  }

  name() {
    const c = this.peek()
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    if (!isBareName(c)) this.fail('expected a name')
    const start = this.i
    while (isBareName(this.peek())) this.i += 1
    return this.s.slice(start, this.i)
  }

  /** Names joined by dots, with spaces and tabs allowed around each dot. */
  dottedName() {
    const parts = [this.name()]
    for (;;) {
      const mark = this.i
      this.spaces()
      if (this.peek() !== '.') {
        this.i = mark
        return parts
      }
      this.i += 1
      this.spaces()
      parts.push(this.name())
    }
  }

  value(prefix) {
    this.spaces()
    const c = this.peek()
    if (this.spent() || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return { kind: 'string', value: this.basicString() }
    if (c === "'") return { kind: 'string', value: this.literalString() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inlineTable(prefix)
    const start = this.i
    while (!this.done()) {
      const ch = this.s[this.i]
      if (isSpace(ch) || ch === ',' || ch === ']' || ch === '}') break
      this.i += 1
    }
    return this.scalar(this.s.slice(start, this.i))
  }

  scalar(text) {
    if (text === 'true') return { kind: 'boolean', value: true }
    if (text === 'false') return { kind: 'boolean', value: false }
    const digits = text.replace(/_/g, '')
    if (INTEGER.test(text)) return { kind: 'integer', value: Number(digits) }
    if (FLOAT.test(text)) return { kind: 'float', value: Number(digits) }
    this.fail(`invalid value ${text}`)
  }

  array(prefix) {
    this.i += 1
    const items = []
    for (;;) {
      this.spaces()
      if (this.spent()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.i += 1
        return { kind: 'array', items, aot: false }
      }
      items.push(this.value(prefix))
      this.spaces()
      if (this.spent()) this.fail('unterminated array')
      const ch = this.peek()
      if (ch === ']') {
        this.i += 1
        return { kind: 'array', items, aot: false }
      }
      if (ch !== ',') this.fail('unterminated array')
      this.i += 1
    }
  }

  inlineTable(prefix) {
    this.i += 1
    const table = newTable()
    this.spaces()
    if (this.spent()) this.fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i += 1
      return table
    }
    for (;;) {
      this.spaces()
      if (this.spent()) this.fail('unterminated inline table')
      const parts = this.dottedName()
      this.spaces()
      if (this.spent() || this.peek() !== '=') this.fail('expected = in an inline table')
      this.i += 1
      const value = this.value(parts.reduce(pathJoin, prefix))
      this.assign(table, parts, value, prefix)
      this.spaces()
      if (this.spent()) this.fail('unterminated inline table')
      const ch = this.peek()
      if (ch === '}') {
        this.i += 1
        return table
      }
      if (ch !== ',') this.fail('unterminated inline table')
      this.i += 1
    }
  }

  /** Walks the dots of a name, making the tables the walk needs on the way. */
  walk(table, parts, prefix) {
    let current = table
    let path = prefix
    for (let k = 0; k < parts.length - 1; k += 1) {
      path = pathJoin(path, parts[k])
      let node = current.entries.get(parts[k])
      if (node === undefined) {
        node = newTable()
        current.entries.set(parts[k], node)
      } else if (node.kind === 'array' && node.aot) {
        node = node.items[node.items.length - 1]
      } else if (node.kind !== 'table') {
        this.fail(`${path} is not a table`)
      }
      current = node
    }
    return { table: current, path }
  }

  assign(table, parts, value, prefix) {
    const { table: owner, path } = this.walk(table, parts, prefix)
    const last = parts[parts.length - 1]
    if (owner.entries.has(last)) this.fail(`key ${pathJoin(path, last)} is defined twice`)
    owner.entries.set(last, value)
  }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable()
  let current = root
  let currentPath = ''

  for (let n = 0; n < lines.length; n += 1) {
    const line = new Line(lines[n], n + 1)
    line.spaces()
    if (line.spent()) continue

    if (line.peek() === '[') {
      const made = header(line, root)
      current = made.table
      currentPath = made.path
      continue
    }

    const parts = line.dottedName()
    line.spaces()
    if (line.peek() !== '=') line.fail('expected key = value')
    line.i += 1
    const value = line.value(parts.reduce(pathJoin, currentPath))
    line.assign(current, parts, value, currentPath)
    line.spaces()
    if (!line.spent()) line.fail('trailing text after a value')
  }

  return root
}

/** `[name]` and `[[name]]`, which choose the table the next keys land in. */
function header(line, root) {
  line.i += 1
  let doubled = false
  if (line.peek() === '[') {
    doubled = true
    line.i += 1
  }
  line.spaces()
  const parts = line.dottedName()
  line.spaces()
  if (line.peek() !== ']') line.fail('unterminated table header')
  line.i += 1
  if (doubled) {
    if (line.peek() !== ']') line.fail('unterminated table header')
    line.i += 1
  }
  line.spaces()
  if (!line.spent()) line.fail('trailing text after a table header')

  const { table: owner, path: prefix } = line.walk(root, parts, '')
  const last = parts[parts.length - 1]
  const path = pathJoin(prefix, last)
  let node = owner.entries.get(last)

  if (doubled) {
    if (node === undefined) {
      node = { kind: 'array', items: [], aot: true }
      owner.entries.set(last, node)
    } else if (node.kind !== 'array' || !node.aot) {
      line.fail(`${path} is not an array of tables`)
    }
    const fresh = newTable()
    node.items.push(fresh)
    return { table: fresh, path }
  }

  if (node === undefined) {
    node = newTable()
    owner.entries.set(last, node)
  } else if (node.kind !== 'table') {
    line.fail(`${path} is not a table`)
  } else if (node.header) {
    line.fail(`table ${path} is defined twice`)
  }
  node.header = true
  return { table: node, path }
}
"}

